import csv
import io
import re
from typing import Any


_NUMBER = re.compile(r"^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$")


def _is_number(value: str) -> bool:
    value = value.strip()
    return bool(value) and bool(_NUMBER.fullmatch(value))


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = list(reader)

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 4
    first_data = None
    minimum_numeric = min(2, expected_width)

    for index, record in enumerate(records):
        nonempty = [value for value in record if value.strip()]
        if len(nonempty) >= minimum_numeric and all(_is_number(value) for value in nonempty):
            first_data = index
            break

    if first_data is None:
        nonempty_indices = [i for i, record in enumerate(records) if record]
        if not nonempty_indices:
            return {"columns": [], "rows": []}
        header_index = nonempty_indices[0]
        header_records = [records[header_index]]
        data_records = records[header_index + 1:]
    else:
        preceding = records[:first_data]
        nonempty_preceding = [record for record in preceding if record]
        if not nonempty_preceding:
            header_records = []
        else:
            last = nonempty_preceding[-1]
            header_records = [last]
            if len(nonempty_preceding) >= 2:
                parent = nonempty_preceding[-2]
                if (
                    len(parent) == len(last)
                    and any(not value.strip() for value in parent)
                    and any(value.strip() for value in parent)
                    and any(value.strip() for value in last)
                ):
                    header_records = [parent, last]
        data_records = records[first_data:]

    width = max(
        expected_width,
        max((len(record) for record in records), default=0),
        max((len(record) for record in header_records), default=0),
    )

    columns = []
    if len(header_records) == 2:
        parent, child = header_records
        parent = parent + [""] * (width - len(parent))
        child = child + [""] * (width - len(child))
        current_parent = ""
        for i in range(width):
            if parent[i].strip():
                current_parent = parent[i].strip()
            sub = child[i].strip()
            parts = [part for part in (current_parent, sub) if part]
            columns.append(" ".join(parts))
    elif header_records:
        header = header_records[-1] + [""] * (width - len(header_records[-1]))
        columns = [value.strip() for value in header]
    else:
        columns = []

    if len(columns) < width:
        columns.extend([""] * (width - len(columns)))
    for i, name in enumerate(columns):
        if not name:
            columns[i] = f"column_{i + 1}"

    rows = []
    for record in data_records:
        rows.append(record[:width] + [""] * max(0, width - len(record)))

    return {"columns": columns, "rows": rows}
